cd /tmp/sv-c826933b4f164ccd96135d55c891e55e
# Get function symbols sorted, find enclosing functions for 0x2f4b20 and 0x2f4c84
nm -C libmonosgen-2.0.so.dbg 2>/dev/null | awk '$2 ~ /[tTwW]/ && $1 != "" {print $1, $3}' | sort | awk '
{
  addr=strtonum("0x"$1);
  addrs[NR]=addr; names[NR]=$2; count=NR;
}
END {
  targets[1]=0x2f4b20; targets[2]=0x2f4c84;
  for (t=1; t<=2; t++) {
    target=targets[t];
    best_addr=0; best_name="??";
    for (i=1; i<=count; i++) {
      if (addrs[i] <= target && addrs[i] > best_addr) {
        best_addr=addrs[i]; best_name=names[i];
      }
    }
    printf "0x%x => %s (at 0x%x, offset +0x%x)\n", target, best_name, best_addr, target-best_addr;
  }
}'

