arguments.command:
cd /tmp/sv-c826933b4f164ccd96135d55c891e55e
# The Cortex-A53 erratum thunks patch specific instruction addresses
# The thunk name format is __CortexA53843419_XXXXXX where XXXXXX is the page+offset of patched instruction
# These are in a veneer section. Let's look at what DWARF says for these addresses using readelf
# Actually, let's try to use the DWARF line info more directly with --dwarf=decodedline
aarch64-linux-gnu-readelf --debug-dump=decodedline libmonosgen-2.0.so.dbg 2>/dev/null | awk '
/^CU:/ { cu=$0 }
{
  if ($1 ~ /^0x/) {
    addr = strtonum($1)
    if (addr >= 0x2f4b00 && addr <= 0x2f4d00) print $0
  }
}' | head -20
echo "==="
# Also check: the thunk is at 0x2f4b20 and branches back to the real code
# Let's look at what's around 0x2d3 page area in sgen
nm -C libmonosgen-2.0.so.dbg 2>/dev/null | awk '$2 ~ /[tTwW]/ && $3 !~ /^\$/' | sort | awk '
{
  addr=strtonum("0x"$1);
  if (addr >= 0x2d2000 && addr <= 0x2d4000) print $0
}'

